async function setup(t){const a=createFirebaseEmulatorAdapter();t.after(()=>a.close());const uid='reserve-'+randomUUID(),email=uid+'@example.test',password='Fictitious-test-42!';await a.auth.createUser({uid,email,password});const response=await fetch('http://127.0.0.1:9099/identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=fake',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password,returnSecureToken:true})});const header='Bearer '+(await response.json()).idToken;
 const scopes=[];for(let j=0;j<2;j++){let record=newDemo();record.ledger.state.config.tenantId='reservation-'+randomUUID();for(let i=0;i<8;i++)record=advance(record,record.ledger.revision).record;const scope={tenantId:record.ledger.state.config.tenantId,campaignId:record.ledger.state.config.campaignId,teamId:'explorateurs',milestoneNumber:2};await a.db.doc(`tenants/${scope.tenantId}/campaigns/${scope.campaignId}`).set({payload:JSON.stringify(record)});scopes.push(scope);}
 const grant=a.db.doc('giftOperators/'+uid);await grant.set({uid,active:true,campaigns:scopes.map(({tenantId,campaignId})=>({tenantId,campaignId}))});const catalog=demoSupplierCatalog();catalog.masterById=Object.fromEntries(catalog.products.map(p=>[p.id,{sku:p.id,stockQuantity:1,vatBasisPoints:600}]));const catalogDocument='supplierCatalog/'+uid;await a.db.doc(catalogDocument).set(catalog);const service=createGiftOperations(a,{catalogDocument,now:()=> '2026-08-17T12:00:00Z'});
 async function prepare(scope){const fees={packagingCents:500,transportCents:500},p=await service.anticipate(header,{...scope,...fees});await service.saveProposal(header,{...scope,...fees,revision:0,mutationId:randomUUID(),reason:'Proposition fictive',fingerprint:p.fingerprint});await service.reviewProposal(header,{...scope,revision:1,mutationId:randomUUID(),reason:'Revue fictive'});return p;}
 const reserve=scope=>({...scope,proposalRevision:2,mutationId:randomUUID(),reason:'Réservation fictive contrôlée',conditions:'Blocage interne réversible, aucun engagement fournisseur'});
 const release=(scope,revision=1)=>({...scope,revision,mutationId:randomUUID(),reason:'Libération fictive contrôlée'});
 return {a,uid,header,scopes,grant,catalog,catalogDocument,service,prepare,reserve,release};
}
test('competing tenants cannot reserve the same declared unit; durable retries and release conserve stock',async t=>{
 const {a,header,scopes,service,prepare,reserve,release,catalogDocument,catalog,grant}=await setup(t);for(const s of scopes)await prepare(s);const requests=scopes.map(reserve),results=await Promise.allSettled(requests.map(i=>service.reserveProposal(header,i)));assert.equal(results.filter(r=>r.status==='fulfilled').length,1);assert.equal(results.find(r=>r.status==='rejected').reason.status,422);const winner=results.findIndex(r=>r.status==='fulfilled'),loser=1-winner,scope=scopes[winner];
 const list=await service.reservations(header);assert.equal(list.rows.length,1);assert.ok(list.rows[0].lines.every(l=>l.unreservedQuantity===0));assert.doesNotMatch(JSON.stringify(list),/fingerprint|choices|privateContactRequested/);assert.deepEqual((await a.db.doc(catalogDocument).get()).data(),catalog);
 assert.equal((await service.reserveProposal(header,requests[winner])).alreadyApplied,true);await assert.rejects(service.reserveProposal(header,{...requests[winner],conditions:'Autres conditions'}),{status:409});
 const prefresh=await service.anticipate(header,{...scope,packagingCents:500,transportCents:500});await assert.rejects(service.saveProposal(header,{...scope,packagingCents:500,transportCents:500,fingerprint:prefresh.fingerprint,revision:2,mutationId:randomUUID(),reason:'Modification interdite pendant réservation'}),{status:409});
 const unreserve=release(scope);const twice=await Promise.all([service.releaseReservation(header,unreserve),service.releaseReservation(header,unreserve)]);assert.equal(twice.filter(x=>!x.alreadyApplied).length,1);assert.equal((await service.reserveProposal(header,requests[winner])).revision,1);assert.equal((await service.reservations(header)).rows[0].status,'released');await service.reserveProposal(header,requests[loser]);await assert.rejects(service.releaseReservation(header,release(scope)),{status:409});
 await service.releaseReservation(header,release(scopes[loser]));await service.reserveProposal(header,reserve(scope));assert.equal((await service.releaseReservation(header,unreserve)).revision,2);let renewed=(await service.reservations(header)).rows.find(r=>r.tenantId===scope.tenantId);assert.equal(renewed.status,'reserved');assert.equal(renewed.revision,3);await assert.rejects(service.releaseReservation(header,release(scope)),{status:409});await service.releaseReservation(header,release(scope,3));
 for(const s of scopes){const ref=a.db.doc(`tenants/${s.tenantId}/campaigns/${s.campaignId}`);assert.equal((await ref.collection('giftFulfillments').get()).size,0);assert.equal(Object.keys(JSON.parse((await ref.get()).data().payload).ledger.state.entitlements).length,4);}
 await grant.update({campaigns:[{tenantId:scope.tenantId,campaignId:scope.campaignId}]});const filtered=await service.reservations(header);assert.equal(filtered.rows.length,1);assert.ok(filtered.rows.every(r=>r.tenantId===scope.tenantId));await assert.rejects(service.releaseReservation(header,release(scopes[loser])),{status:403});await grant.update({active:false});await assert.rejects(service.reservations(header),{status:403});await assert.rejects(service.reserveProposal(header,requests[winner]),{status:403});await assert.rejects(service.releaseReservation(header,unreserve),{status:403});
});
